public String summarize() {
    StringBuilder summary = new StringBuilder();
    summary.append("Constraint: ").append(constraintRef).append("\n");
    summary.append("Weight: ").append(weight).append("\n");
    summary.append("Score: ").append(score).append("\n");
    summary.append("Match count: ").append(matchCount).append("\n");

    if (matches == null) {
        summary.append("Matches: Analysis not available\n");
    } else if (matches.isEmpty()) {
        summary.append("Matches: None\n");
    } else {
        summary.append("Matches:\n");
        int limit = Math.min(matches.size(), DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT);
        for (int i = 0; i < limit; i++) {
            MatchAnalysis<Score_> match = matches.get(i);
            summary.append("  - Score: ").append(match.score())
                   .append(", Justification: ").append(match.justification())
                   .append("\n");
        }
        if (matches.size() > DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT) {
            summary.append("  ... and ").append(matches.size() - DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT)
                   .append(" more matches\n");
        }
    }

    return summary.toString();
}

