import java.beans.PropertyDescriptor;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Set;
import java.util.stream.Collectors;

public <T, S extends T, I> T mergeBeans(S source, T target, Class<I> sourceInterfaceClazz, boolean overrideNonNullTargetValues) {
    if (source == null || target == null || sourceInterfaceClazz == null) {
        return target;
    }

    Set<String> interfaceGetterNames = Arrays.stream(sourceInterfaceClazz.getMethods())
        .filter(method -> method.getName().startsWith("get") && method.getParameterCount() == 0)
        .map(Method::getName)
        .collect(Collectors.toSet());

    BeanWrapperImpl sourceWrapper = new BeanWrapperImpl(source);
    BeanWrapperImpl targetWrapper = new BeanWrapperImpl(target);

    for (PropertyDescriptor pd : sourceWrapper.getPropertyDescriptors()) {
        String propertyName = pd.getName();
        Method readMethod = pd.getReadMethod();

        if (readMethod == null || !interfaceGetterNames.contains(readMethod.getName())) {
            continue;
        }

        if (targetWrapper.isWritableProperty(propertyName)) {
            Object sourceValue = sourceWrapper.getPropertyValue(propertyName);

            if (sourceValue != null) {
                if (overrideNonNullTargetValues) {
                    targetWrapper.setPropertyValue(propertyName, sourceValue);
                } else {
                    Object targetValue = targetWrapper.getPropertyValue(propertyName);
                    if (targetValue == null) {
                        targetWrapper.setPropertyValue(propertyName, sourceValue);
                    }
                }
            }
        }
    }

    return target;
}

